import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout"
    >
      {children}
    </div>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
import CheckIcon from "@hugeicons/core-free-icons/CheckIcon";
import CopyIcon from "@hugeicons/core-free-icons/CopyIcon";

import { Button } from "@/registry/erbium/ui/button";
import { useCopyToClipboard } from "@/registry/erbium/hooks/use-copy-to-clipboard";
import { StatefulIcon } from "@/registry/erbium/ui/stateful-icon";

export default function StatefulIconDemo() {
  const { copyToClipboard, isCopied } = useCopyToClipboard({ timeout: 1200 });

  return (
    <Button
      aria-label={isCopied ? "Copied" : "Copy example text"}
      onClick={() => copyToClipboard("Stateful icons animate between states.")}
      size="icon"
      variant="outline"
    >
      <StatefulIcon
        state={isCopied ? "success" : "idle"}
        icons={{
          idle: <HugeiconsIcon icon={CopyIcon} className="size-4" />,
          success: <HugeiconsIcon icon={CheckIcon} className="size-4" />,
        }}
      />
    </Button>
  );
}

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/registry/erbium/ui/collapsible";

import {
  ExpandableChevron as ExpandableChevronIcon,
  SidebarToggleIcon as SidebarToggleIconGraphic,
  ThemeToggleIcon as ThemeToggleIconGraphic,
} from "@/registry/erbium/ui/stateful-icon";

import { useState } from "react";

export function ExpandableChevronExample() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <Collapsible className="w-72" open={isOpen} onOpenChange={setIsOpen}>
      <CollapsibleTrigger className="flex w-full items-center rounded-lg border px-3 py-2 text-start">
        Project details
        <ExpandableChevronIcon className="ms-auto" isOpen={isOpen} />
      </CollapsibleTrigger>
      <CollapsibleContent className="px-3 py-2 text-sm text-muted-foreground">
        The two chevrons exchange positions as this section opens and closes.
      </CollapsibleContent>
    </Collapsible>
  );
}

export function SidebarToggleIconExample({ side }: { side: "left" | "right" }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <button
      aria-expanded={isOpen}
      aria-label={`${isOpen ? "Close" : "Open"} ${side} sidebar`}
      className="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm"
      onClick={() => setIsOpen((open) => !open)}
      type="button"
    >
      <SidebarToggleIconGraphic isOpen={isOpen} side={side} />
      {side === "left" ? "Left" : "Right"} sidebar
    </button>
  );
}

export function ThemeToggleIconExample() {
  const [theme, setTheme] = useState<"light" | "dark">("light");

  return (
    <button
      aria-label={`Switch to ${theme === "light" ? "dark" : "light"} theme`}
      className="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm"
      onClick={() => setTheme((current) => (current === "light" ? "dark" : "light"))}
      type="button"
    >
      <ThemeToggleIconGraphic theme={theme} />
      {theme === "light" ? "Light" : "Dark"} theme
    </button>
  );
}

